#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/mem_blocks.h>

#define NUM_BLOCKS 4
#define BLOCK_SIZE 64

K_MEM_BLOCK_POOL_DEFINE(k_mem_block_pool, BLOCK_SIZE, BLOCK_SIZE, NUM_BLOCKS, 4);

static struct k_mem_block_pool_stats stats;

static void *block_ptrs[NUM_BLOCKS + 1]; /* +1 for testing overflow */

static void test_mem_blocks_runtime_stats(void)
{
	int status;
	size_t i;

	/* 1. Initial state: all blocks free */
	k_mem_block_pool_stats_get(&k_mem_block_pool, &stats);
	zassert_equal(stats.num_free, NUM_BLOCKS, "Initial free blocks mismatch");
	zassert_equal(stats.num_used, 0, "Initial used blocks mismatch");

	/* 2. Allocate all blocks */
	for (i = 0; i < NUM_BLOCKS; i++) {
		status = k_mem_block_get(&k_mem_block_pool, &block_ptrs[i], K_NO_WAIT);
		zassert_equal(status, 0, "Failed to get block %zu", i);
	}

	k_mem_block_pool_stats_get(&k_mem_block_pool, &stats);
	zassert_equal(stats.num_free, 0, "Free blocks after full allocation mismatch");
	zassert_equal(stats.num_used, NUM_BLOCKS, "Used blocks after full allocation mismatch");

	/* 3. Try to allocate one more block (expect failure) */
	status = k_mem_block_get(&k_mem_block_pool, &block_ptrs[NUM_BLOCKS], K_NO_WAIT);
	zassert_not_equal(status, 0, "Expected allocation to fail when pool is full");

	/* 4. Free all blocks */
	for (i = 0; i < NUM_BLOCKS; i++) {
		status = k_mem_block_free(&k_mem_block_pool, &block_ptrs[i]);
		zassert_equal(status, 0, "Failed to free block %zu", i);
	}

	k_mem_block_pool_stats_get(&k_mem_block_pool, &stats);
	zassert_equal(stats.num_free, NUM_BLOCKS, "Free blocks after full deallocation mismatch");
	zassert_equal(stats.num_used, 0, "Used blocks after full deallocation mismatch");

	/* 5. Try to free an already freed block (expect failure) */
	status = k_mem_block_free(&k_mem_block_pool, &block_ptrs[0]);
	zassert_not_equal(status, 0, "Expected free to fail for already freed block");

	/* 6. Try to free an invalid pointer (expect failure) */
	void *invalid_ptr = (void *)0xDEADBEEF;
	status = k_mem_block_free(&k_mem_block_pool, &invalid_ptr);
	zassert_not_equal(status, 0, "Expected free to fail for invalid pointer");
}

static void test_mem_blocks_init_stats(void)
{
	/* Initial state: all blocks free */
	k_mem_block_pool_stats_get(&k_mem_block_pool, &stats);
	zassert_equal(stats.num_free, NUM_BLOCKS, "Initial free blocks mismatch");
	zassert_equal(stats.num_used, 0, "Initial used blocks mismatch");
}

ZTEST_SUITE(lib_mem_blocks_stats_test, NULL, NULL,
		NULL, NULL, NULL);

ZTEST_UNIT(lib_mem_blocks_stats_test, test_mem_blocks_init_stats)
{
	/* This test is covered by the setup of test_mem_blocks_runtime_stats */
	/* No additional assertions needed here as it's implicitly tested. */
}

ZTEST_UNIT(lib_mem_blocks_stats_test, test_mem_blocks_runtime_stats)
{
	test_mem_blocks_runtime_stats();
}
